type purchaseMemberBurdenJoins[Q dialect.Joinable] struct {
	typ             string
	HouseholdMember modAs[Q, householdMemberColumns]
	PoolFundingRule modAs[Q, poolFundingRuleColumns]
	PurchaseItem    modAs[Q, purchaseItemColumns]
}

func (j purchaseMemberBurdenJoins[Q]) aliasedAs(alias string) purchaseMemberBurdenJoins[Q] {
	return buildPurchaseMemberBurdenJoins[Q](buildPurchaseMemberBurdenColumns(alias), j.typ)
}

func buildPurchaseMemberBurdenJoins[Q dialect.Joinable](cols purchaseMemberBurdenColumns, typ string) purchaseMemberBurdenJoins[Q] {
	return purchaseMemberBurdenJoins[Q]{
		typ: typ,
		HouseholdMember: modAs[Q, householdMemberColumns]{
			c: HouseholdMembers.Columns,
			f: func(to householdMemberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, HouseholdMembers.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.MemberID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
		PoolFundingRule: modAs[Q, poolFundingRuleColumns]{
			c: PoolFundingRules.Columns,
			f: func(to poolFundingRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PoolFundingRules.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PoolID.EQ(cols.PoolID), to.Version.EQ(cols.FundingRuleVersion),
					))
				}

				return mods
			},
		},
		PurchaseItem: modAs[Q, purchaseItemColumns]{
			c: PurchaseItems.Columns,
			f: func(to purchaseItemColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchaseItems.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PurchaseID.EQ(cols.PurchaseID), to.ID.EQ(cols.ItemID),
					))
				}

				return mods
			},
		},
	}
}
